INSERT INTO "daily_progress" ("id", "project_id", "site_id", "date", "work_category", "description", "completion_percentage", "remarks", "photos", "documents", "created_by_id", "created_by_name", "verified_by_id", "verified_by_name", "approved_by_id", "approved_by_name", "status", "created_at") VALUES ('dpr-001', 'PRJ-101', 'sit-001', '2026-07-30', 'Mechanical Piping Fabrication', 'Completed fit-up and TIG welding of 12-inch Schedule 80 carbon steel spool joints #14 through #18. NDT dye-penetrant test verified.', 45, 'Pre-heating held at 150°C. 4 welders engaged on 12hr shift.', '["https://images.unsplash.com/photo-1504307651254-35680f356dfd?auto=format&fit=crop&w=600&q=80"]', '["https://images.unsplash.com/photo-1541888946425-d0fbb186a5b3?auto=format&fit=crop&w=600&q=80"]', 'usr-inc-003', 'Tariq Al-Farsi', 'usr-mgr-002', 'Sarah Al-Mansoor', 'usr-admin-001', 'Abdul Vajid EK', 'APPROVED', '2026-07-30T17:30:00.000Z');
